const FINAL_ANIMATION_BY_KEY = new Map(HMH_FINAL_ANIMATION_COMPLETION_PACK.assets.map((asset) => [asset.key, Object.freeze(asset)]));
export function finalAnimationAssetByKey(key) { return FINAL_ANIMATION_BY_KEY.get(key) ?? null; }
export function completionAssetsForActor(actorId) { return Object.freeze(HMH_FINAL_ANIMATION_COMPLETION_PACK.assets.filter((asset) => asset.actorId === actorId)); }
export function completionCoverageSummary() {
  const heroActors = HMH_FINAL_ANIMATION_COMPLETION_PACK.actors.filter((actor) => actor.role === 'hero');
  const enemyActors = HMH_FINAL_ANIMATION_COMPLETION_PACK.actors.filter((actor) => actor.role === 'enemy');
  const missingAssets = [];
  for (const actor of HMH_FINAL_ANIMATION_COMPLETION_PACK.actors) {
    for (const state of actor.states ?? []) { if (!FINAL_ANIMATION_BY_KEY.has(`${actor.role}/${actor.id}/${state}`)) missingAssets.push(`${actor.role}/${actor.id}/${state}`); }
  }
  return Object.freeze({ heroActors: heroActors.length, enemyActors: enemyActors.length, heroStates: Object.freeze([...HMH_FINAL_ANIMATION_COMPLETION_PACK.heroPolishStates]), enemyStates: Object.freeze([...HMH_FINAL_ANIMATION_COMPLETION_PACK.enemyReadabilityStates]), totalAssets: HMH_FINAL_ANIMATION_COMPLETION_PACK.assets.length, missingAssets: Object.freeze(missingAssets) });
}
